cd /app && python3 -c "
import cv2, numpy as np
cap = cv2.VideoCapture('example_video.mp4')
frames = []
while True:
    ok, f = cap.read()
    if not ok: break
    frames.append(f)
cap.release()
f = np.stack([x.astype(np.int16) for x in frames])
med = np.median(f, axis=0)
cands = {}
for i in range(len(frames)):
    d = np.abs(f[i] - med).max(axis=2)
    m = (d > 12).astype(np.uint8)
    m = cv2.morphologyEx(m, cv2.MORPH_OPEN, np.ones((3,3),np.uint8))
    n, lab, stats, cent = cv2.connectedComponentsWithStats(m, 8)
    lst = []
    for c in range(1, n):
        a = stats[c, cv2.CC_STAT_AREA]
        w, h = stats[c, cv2.CC_STAT_WIDTH], stats[c, cv2.CC_STAT_HEIGHT]
        if 20 < a < 400 and w < 60 and h < 120:
            x0, y0 = stats[c, cv2.CC_STAT_LEFT], stats[c, cv2.CC_STAT_TOP]
            lst.append((int(cent[c][0]), int(cent[c][1]), a))
    cands[i] = lst
active = {}
tracks = []
for i in range(len(frames)):
    used = set()
    for (cx, cy, a) in cands[i]:
        best = None
        for tid, (lf, px, py) in active.items():
            if tid in used: continue
            if i - lf > 2: continue
            d = ((cx-px)**2 + (cy-py)**2) ** 0.5
            if d < 15 and (best is None or d < best[1]): best = (tid, d)
        if best is not None:
            tracks[best[0]].append((i, cx, cy, a)); used.add(best[0]); active[best[0]] = (i, cx, cy)
        else:
            tracks.append([(i, cx, cy, a)]); active[len(tracks)-1] = (i, cx, cy)
    for tid in list(active):
        if i - active[tid][0] > 3: del active[tid]
for tid, t in enumerate(tracks):
    if len(t) >= 10:
        fs = [p[0] for p in t]
        print('track %d n=%d f %d..%d path %s' % (tid, len(t), min(fs), max(fs), [(p[0],p[1],p[2]) for p in t[::3]]))
"
